FILES = {
  "server/services/qikink.py": "\"\"\"Qikink Sandbox only. No storefront hooks, wallet calls, or automatic order retries.\"\"\"\nfrom __future__ import annotations\n\nimport asyncio\nimport hashlib\nimport json\nimport os\nimport sqlite3\nimport time\nfrom contextlib import closing\nfrom io import BytesIO\nfrom pathlib import Path\nfrom typing import Literal\nfrom urllib.parse import urlsplit\n\nimport httpx\nfrom PIL import Image\nfrom pydantic import BaseModel, ConfigDict, Field, field_validator\n\nSANDBOX_BASE = \"https://sandbox.qikink.com\"\nDEFAULT_JOURNAL = Path(__file__).resolve().parents[1] / \"data\" / \"qikink_sandbox.db\"\n\n\nclass QikinkError(RuntimeError):\n    \"\"\"Safe to display: never contains response bodies, tokens, or request data.\"\"\"\n\n\nclass DuplicateBlocked(QikinkError):\n    pass\n\n\nclass OutcomeUnknown(QikinkError):\n    pass\n\n\nclass ShippingAddress(BaseModel):\n    model_config = ConfigDict(extra=\"forbid\", str_strip_whitespace=True)\n    first_name: str = Field(min_length=1, max_length=20)\n    last_name: str = Field(default=\"\", max_length=20)\n    address1: str = Field(min_length=1, max_length=90)\n    address2: str = Field(default=\"\", max_length=90)\n    phone: str = Field(min_length=1, max_length=15)\n    email: str = Field(min_length=1, max_length=254)\n    city: str = Field(min_length=1, max_length=40)\n    zip: str = Field(pattern=r\"^[0-9]{6}$\")\n    province: str = Field(min_length=1, max_length=40)\n    # Current Sandbox test fixtures are limited to India.\n    country_code: Literal[\"IN\"] = \"IN\"\n\n\nclass PlainOrder(BaseModel):\n    model_config = ConfigDict(extra=\"forbid\", str_strip_whitespace=True)\n    reference: str = Field(pattern=r\"^[a-z0-9_]{1,15}$\")\n    sku: str = Field(min_length=1, max_length=50)\n    quantity: int = Field(default=1, ge=1, le=100, strict=True)\n    price: str = \"1\"\n    total_order_value: str = \"1\"\n    shipping_address: ShippingAddress\n\n    @field_validator(\"price\", \"total_order_value\")\n    @classmethod\n    def numeric_amount(cls, value: str) -> str:\n        from decimal import Decimal, InvalidOperation\n        try:\n            amount = Decimal(value)\n        except InvalidOperation:\n            raise ValueError(\"Amount must be numeric\") from None\n        if not amount.is_finite() or amount < 0:\n            raise ValueError(\"Amount must be finite and non-negative\")\n        return format(amount, \"f\")\n\n    def payload(self) -> dict:\n        address = self.shipping_address.model_dump(exclude_defaults=True)\n        address[\"country_code\"] = self.shipping_address.country_code\n        return {\n            \"order_number\": self.reference,\n            \"qikink_shipping\": \"1\",\n            \"gateway\": \"Prepaid\",\n            \"total_order_value\": self.total_order_value,\n            \"line_items\": [{\n                \"search_from_my_products\": 0,\n                \"print_type_id\": \"1\",\n                \"quantity\": str(self.quantity),\n                \"price\": self.price,\n                \"sku\": self.sku,\n            }],\n            \"shipping_address\": address,\n        }\n\n\nclass PrintDesign(BaseModel):\n    \"\"\"Fully specified DTG design; blank fields for reused codes are not supported.\"\"\"\n    model_config = ConfigDict(extra=\"forbid\", str_strip_whitespace=True)\n    design_code: str = Field(pattern=r\"^[a-zA-Z0-9_-]{1,20}$\")\n    width_inches: float = Field(default=2, gt=0, le=16, allow_inf_nan=False)\n    height_inches: float = Field(default=2, gt=0, le=20, allow_inf_nan=False)\n    placement_sku: Literal[\"fr\", \"bk\", \"lp\", \"rp\", \"rs\", \"ls\"] = \"fr\"\n    design_link: str = Field(min_length=1, max_length=512)\n    mockup_link: str = Field(min_length=1, max_length=512)\n\n    @field_validator(\"design_link\", \"mockup_link\")\n    @classmethod\n    def public_https(cls, value: str) -> str:\n        parsed = urlsplit(value)\n        if (parsed.scheme != \"https\" or not parsed.hostname or parsed.username is not None\n                or parsed.password is not None or parsed.query or parsed.fragment):\n            raise ValueError(\"Use a public HTTPS image URL without credentials, query or fragment\")\n        if parsed.hostname not in {\"thebookswanderer.com\", \"www.thebookswanderer.com\"} or parsed.port not in (None, 443):\n            raise ValueError(\"Sandbox artwork must be hosted on the store domain\")\n        return value\n\n\nclass PrintedOrder(PlainOrder):\n    design: PrintDesign\n\n    def payload(self) -> dict:\n        payload = super().payload()\n        payload[\"line_items\"][0][\"designs\"] = [self.design.model_dump()]\n        return payload\n\n\ndef _digest(value: dict) -> str:\n    return hashlib.sha256(json.dumps(value, sort_keys=True, separators=(\",\", \":\")).encode()).hexdigest()\n\n\ndef _order_id(value) -> str | None:\n    if isinstance(value, bool) or not isinstance(value, (str, int)):\n        return None\n    text = str(value)\n    return text if text.isascii() and text.isdigit() and int(text) > 0 else None\n\n\nclass SandboxJournal:\n    \"\"\"Separate SQLite journal. Stores hashes, references and IDs, never addresses/tokens.\n\n    pending/uncertain records must be reconciled manually; they are never retried.\n    Atomic reservations protect multiple processes sharing this same database.\n    \"\"\"\n\n    def __init__(self, path: Path = DEFAULT_JOURNAL):\n        self.path = Path(path)\n        self.path.parent.mkdir(parents=True, exist_ok=True)\n        with closing(self._connect()) as db, db:\n            db.execute(\"\"\"CREATE TABLE IF NOT EXISTS qikink_orders (\n                account TEXT NOT NULL, reference TEXT NOT NULL, payload_hash TEXT NOT NULL,\n                state TEXT NOT NULL, order_id TEXT, updated_at REAL NOT NULL,\n                PRIMARY KEY (account, reference))\"\"\")\n\n    def _connect(self):\n        return sqlite3.connect(self.path, timeout=10)\n\n    def reserve(self, account: str, order: PlainOrder | PrintedOrder, known_id: str | None = None) -> dict:\n        fingerprint = _digest(order.payload())\n        with closing(self._connect()) as db, db:\n            db.execute(\"BEGIN IMMEDIATE\")\n            row = db.execute(\n                \"SELECT payload_hash, state, order_id FROM qikink_orders WHERE account=? AND reference=?\",\n                (account, order.reference),\n            ).fetchone()\n            if row:\n                if row[0] != fingerprint:\n                    raise DuplicateBlocked(\"Reference already registered with a different payload\")\n                if row[1] == \"created\":\n                    if known_id is not None and known_id != row[2]:\n                        raise DuplicateBlocked(\"Reference already linked to a different order ID\")\n                    return {\"state\": \"created\", \"order_id\": row[2], \"cached\": True}\n                if known_id is not None:\n                    raise DuplicateBlocked(\"Existing reservation requires manual reconciliation\")\n                if row[1] != \"not_sent\":\n                    raise DuplicateBlocked(\"Reference blocked; inspect the journal before any resubmission\")\n                db.execute(\"UPDATE qikink_orders SET state='pending', updated_at=? WHERE account=? AND reference=?\",\n                           (time.time(), account, order.reference))\n            else:\n                db.execute(\"INSERT INTO qikink_orders VALUES (?, ?, ?, ?, ?, ?)\",\n                           (account, order.reference, fingerprint,\n                            \"created\" if known_id else \"pending\", known_id, time.time()))\n        return {\"state\": \"created\" if known_id else \"pending\", \"order_id\": known_id, \"cached\": False}\n\n    def finish(self, account: str, reference: str, state: str, order_id: str | None = None):\n        with closing(self._connect()) as db, db:\n            db.execute(\"UPDATE qikink_orders SET state=?, order_id=?, updated_at=? WHERE account=? AND reference=?\",\n                       (state, order_id, time.time(), account, reference))\n\n    def get(self, account: str, reference: str) -> dict | None:\n        with closing(self._connect()) as db:\n            row = db.execute(\"SELECT state, order_id FROM qikink_orders WHERE account=? AND reference=?\",\n                             (account, reference)).fetchone()\n        return {\"reference\": reference, \"state\": row[0], \"order_id\": row[1]} if row else None\n\n\nclass SandboxClient:\n    def __init__(self, client_id: str, client_secret: str, journal: SandboxJournal,\n                 *, transport: httpx.AsyncBaseTransport | None = None):\n        if os.getenv(\"QIKINK_ENV\", \"sandbox\").strip().lower() != \"sandbox\":\n            raise QikinkError(\"Only QIKINK_ENV=sandbox is supported\")\n        if not client_id.strip() or not client_secret.strip():\n            raise QikinkError(\"Missing Qikink Sandbox credentials\")\n        self._client_id = client_id.strip()\n        self._secret = client_secret.strip()\n        self.account = hashlib.sha256(self._client_id.encode()).hexdigest()\n        self.journal = journal\n        self._http = httpx.AsyncClient(timeout=30, follow_redirects=False, transport=transport)\n        self._token = \"\"\n        self._expires = 0.0\n        self._auth_lock = asyncio.Lock()\n\n    @classmethod\n    def from_env(cls, journal: SandboxJournal):\n        return cls(os.getenv(\"QIKINK_SANDBOX_CLIENT_ID\", \"\"),\n                   os.getenv(\"QIKINK_SANDBOX_CLIENT_SECRET\", \"\"), journal)\n\n    async def __aenter__(self):\n        return self\n\n    async def __aexit__(self, *args):\n        await self._http.aclose()\n\n    async def authenticate(self) -> None:\n        async with self._auth_lock:\n            if self._token and self._expires > time.monotonic() + 30:\n                return\n            try:\n                response = await self._http.post(SANDBOX_BASE + \"/api/token\", data={\n                    \"ClientId\": self._client_id, \"client_secret\": self._secret,\n                })\n                if response.status_code != 200:\n                    raise QikinkError(f\"Sandbox authentication failed: HTTP {response.status_code}\")\n                data = response.json()\n                token = data.get(\"Accesstoken\")\n                expires = int(data.get(\"expires_in\", 3600))\n                if not isinstance(token, str) or not token.strip() or expires <= 0:\n                    raise ValueError\n            except (httpx.HTTPError, ValueError, TypeError, AttributeError, OverflowError):\n                raise QikinkError(\"Sandbox authentication unavailable or invalid response\") from None\n            self._token = token\n            self._expires = time.monotonic() + expires\n\n    async def create_plain_order(self, order: PlainOrder) -> dict:\n        # Revalidate/copy so callers cannot change nested fields across awaits.\n        order = PlainOrder.model_validate(order.model_dump())\n        return await self._create_order(order)\n\n    async def create_printed_order(self, order: PrintedOrder) -> dict:\n        order = PrintedOrder.model_validate(order.model_dump())\n        return await self._create_order(order)\n\n    async def check_artwork(self, design: PrintDesign) -> None:\n        \"\"\"Read only store-hosted PNG/JPEG files; never forward Qikink headers.\"\"\"\n        try:\n            for url in dict.fromkeys((design.design_link, design.mockup_link)):\n                async with self._http.stream(\"GET\", url, headers={\"Accept-Encoding\": \"identity\"}) as response:\n                    if response.status_code != 200:\n                        raise ValueError\n                    if response.headers.get(\"content-type\", \"\").split(\";\")[0].strip().lower() not in {\"image/png\", \"image/jpeg\"}:\n                        raise ValueError\n                    image_bytes = bytearray()\n                    async for chunk in response.aiter_bytes():\n                        image_bytes.extend(chunk)\n                        if len(image_bytes) > 4 * 1024 * 1024:\n                            raise ValueError\n                with Image.open(BytesIO(image_bytes)) as image:\n                    if image.format not in {\"PNG\", \"JPEG\"} or image.width * image.height > 40_000_000:\n                        raise ValueError\n                    image.verify()\n        except Exception:\n            raise QikinkError(\"Artwork preflight failed; use accessible store-hosted PNG/JPEG files up to 4 MiB\") from None\n\n    async def _create_order(self, order: PlainOrder | PrintedOrder) -> dict:\n        result = self.journal.reserve(self.account, order)\n        if result[\"state\"] == \"created\":\n            return {**result, \"reference\": order.reference}\n        try:\n            if isinstance(order, PrintedOrder):\n                await self.check_artwork(order.design)\n            await self.authenticate()\n        except BaseException:\n            # Artwork/auth failed before any order request: retrying is safe.\n            self.journal.finish(self.account, order.reference, \"not_sent\")\n            raise\n        try:\n            response = await self._http.post(\n                SANDBOX_BASE + \"/api/order/create\", json=order.payload(),\n                headers={\"ClientId\": self._client_id, \"Accesstoken\": self._token},\n            )\n            if response.status_code == 400:\n                self.journal.finish(self.account, order.reference, \"rejected\")\n                raise QikinkError(\"Sandbox rejected the order (HTTP 400); no automatic retry\")\n            if response.status_code != 200:\n                raise ValueError\n            data = response.json()\n            remote_id = _order_id(data.get(\"order_id\"))\n            if str(data.get(\"status_code\")) != \"200\" or remote_id is None:\n                raise ValueError\n        except QikinkError:\n            raise\n        except BaseException as exc:\n            self.journal.finish(self.account, order.reference, \"uncertain\")\n            if isinstance(exc, (KeyboardInterrupt, SystemExit, asyncio.CancelledError)):\n                raise\n            raise OutcomeUnknown(\"Sandbox creation result unknown; do not resubmit\") from None\n        # If this commit fails, pending remains blocked. Never resend to recover it.\n        self.journal.finish(self.account, order.reference, \"created\", remote_id)\n        return {\"state\": \"created\", \"order_id\": remote_id, \"reference\": order.reference, \"cached\": False}\n\n    def remember_existing(self, order: PlainOrder, order_id: str) -> dict:\n        remote_id = _order_id(order_id)\n        if remote_id is None:\n            raise QikinkError(\"Invalid existing order ID\")\n        return self.journal.reserve(self.account, order, known_id=remote_id)\n\n    async def lookup(self, order_id: str) -> dict:\n        remote_id = _order_id(order_id)\n        if remote_id is None:\n            raise QikinkError(\"Invalid order ID\")\n        await self.authenticate()\n        attempts = []\n        for path in (\"/api/order/list\", \"/api/order\"):\n            try:\n                response = await self._http.get(SANDBOX_BASE + path,\n                    params={\"id\": remote_id, \"params\": \"order_id,number,status\"},\n                    headers={\"ClientId\": self._client_id, \"Accesstoken\": self._token})\n                attempt = {\"path\": path, \"http_status\": response.status_code}\n                attempts.append(attempt)\n                if response.status_code != 200:\n                    continue\n                data = response.json()\n                # Only documented top-level order or list/data envelope shapes.\n                if isinstance(data, dict) and data.get(\"success\") is False:\n                    continue\n                records = data.get(\"data\", data) if isinstance(data, dict) else data\n                records = [records] if isinstance(records, dict) else records\n                if isinstance(records, list):\n                    for record in records:\n                        if isinstance(record, dict) and _order_id(record.get(\"order_id\")) == remote_id:\n                            return {\"state\": \"found\", \"order_id\": remote_id,\n                                    \"attempts\": attempts}\n            except (httpx.HTTPError, ValueError, TypeError):\n                if not attempts or attempts[-1][\"path\"] != path:\n                    attempts.append({\"path\": path})\n                attempts[-1][\"response_unavailable\"] = True\n        # Read failure never changes a successful creation journal record.\n        return {\"state\": \"unverified\", \"order_id\": remote_id, \"attempts\": attempts}\n",
  "server/services/qikink_catalog.py": "\"\"\"Offline Qikink catalog planning. Never publishes products or submits orders.\n\nSupplier quotes and FX rates are operator-supplied evidence, not Qikink API\nresponses. A Sandbox order's selling value is never treated as a supplier cost.\n\"\"\"\nfrom __future__ import annotations\n\nimport sqlite3\nfrom datetime import date, datetime\nfrom decimal import Decimal, ROUND_CEILING\nfrom pathlib import Path\nfrom typing import Literal\nfrom zoneinfo import ZoneInfo\n\nfrom pydantic import BaseModel, ConfigDict, Field, model_validator\n\nfrom services.qikink import PrintDesign\n\nDEFAULT_CATALOG = Path(__file__).resolve().parents[1] / \"config/qikink_sandbox_catalog.json\"\nDEFAULT_STORE_DB = Path(__file__).resolve().parents[1] / \"data/store.db\"\n\n\nclass DraftModel(BaseModel):\n    model_config = ConfigDict(extra=\"forbid\", str_strip_whitespace=True)\n\n\nclass Quote(DraftModel):\n    \"\"\"One explicitly itemized quote for ONE unit, SKU, destination and method.\"\"\"\n    sku: str = Field(min_length=1, max_length=50)\n    design: PrintDesign\n    quantity: Literal[1] = 1\n    country: str = Field(pattern=r\"^[A-Z]{2}$\")\n    postal_code: str = Field(min_length=1, max_length=20)\n    method: str = Field(min_length=1, max_length=100)\n    eta_min_days: int = Field(ge=1, le=365)\n    eta_max_days: int = Field(ge=1, le=365)\n    currency: Literal[\"INR\"] = \"INR\"\n    product: Decimal = Field(ge=0, allow_inf_nan=False)\n    printing: Decimal = Field(ge=0, allow_inf_nan=False)\n    packaging: Decimal = Field(ge=0, allow_inf_nan=False)\n    tax: Decimal = Field(ge=0, allow_inf_nan=False)\n    shipping: Decimal = Field(ge=0, allow_inf_nan=False)\n    other: Decimal = Field(ge=0, allow_inf_nan=False)\n    source: str = Field(min_length=1, max_length=300)\n    confirmed_on: date\n    valid_until: date\n\n    @model_validator(mode=\"after\")\n    def consistent(self):\n        if self.valid_until < self.confirmed_on or self.eta_max_days < self.eta_min_days:\n            raise ValueError(\"Inconsistent quote dates or delivery range\")\n        if self.total() <= 0:\n            raise ValueError(\"A zero total is not a confirmed supplier quote\")\n        return self\n\n    def total(self) -> Decimal:\n        return self.product + self.printing + self.packaging + self.tax + self.shipping + self.other\n\n\nclass FX(DraftModel):\n    currency_pair: Literal[\"INR_USD\"] = \"INR_USD\"\n    usd_per_inr: Decimal = Field(gt=0, allow_inf_nan=False)\n    source: str = Field(min_length=1, max_length=300)\n    confirmed_on: date\n    valid_until: date\n\n    @model_validator(mode=\"after\")\n    def consistent(self):\n        if self.valid_until < self.confirmed_on:\n            raise ValueError(\"Inconsistent FX dates\")\n        return self\n\n\nclass DraftVariant(DraftModel):\n    key: str = Field(pattern=r\"^[a-z0-9_-]{1,80}$\")\n    title: str = Field(min_length=1, max_length=300)\n    store_product_id: int | None = Field(default=None, gt=0)\n    store_variant_id: int | None = Field(default=None, gt=0)\n    sku: str = Field(min_length=1, max_length=50)\n    design: PrintDesign\n    mockup_is_placeholder: bool = True\n    sandbox_order_id: str | None = Field(default=None, pattern=r\"^[0-9]+$\")\n    sandbox_reference: str | None = Field(default=None, pattern=r\"^[a-z0-9_]{1,15}$\")\n    cost_quotes: list[Quote] = Field(default_factory=list)\n\n    @model_validator(mode=\"after\")\n    def consistent(self):\n        if (self.store_product_id is None) != (self.store_variant_id is None):\n            raise ValueError(\"Provide both store product and variant IDs, or neither\")\n        if any(q.sku != self.sku for q in self.cost_quotes):\n            raise ValueError(\"Cost quote SKU does not match this variant\")\n        if any(q.design != self.design for q in self.cost_quotes):\n            raise ValueError(\"Cost quote design does not match this variant\")\n        if bool(self.sandbox_order_id) != bool(self.sandbox_reference):\n            raise ValueError(\"Provide both Sandbox reference and order ID\")\n        return self\n\n\nclass DraftCatalog(DraftModel):\n    version: Literal[1] = 1\n    environment: Literal[\"sandbox\"] = \"sandbox\"\n    requested_countries: list[str] = Field(default_factory=list)\n    variants: list[DraftVariant]\n    fx: FX | None = None\n\n    @model_validator(mode=\"after\")\n    def consistent(self):\n        if not self.variants or len({v.key for v in self.variants}) != len(self.variants):\n            raise ValueError(\"Variant keys must be unique and the catalog non-empty\")\n        bindings = [(v.store_product_id, v.store_variant_id) for v in self.variants if v.store_product_id]\n        if len(bindings) != len(set(bindings)):\n            raise ValueError(\"Store variants cannot be mapped more than once\")\n        if len(set(self.requested_countries)) != len(self.requested_countries):\n            raise ValueError(\"Duplicate destination country\")\n        if any(len(c) != 2 or not c.isascii() or not c.isupper() or not c.isalpha() for c in self.requested_countries):\n            raise ValueError(\"Use uppercase two-letter country codes\")\n        return self\n\n\ndef load_catalog(path: Path = DEFAULT_CATALOG) -> DraftCatalog:\n    return DraftCatalog.model_validate_json(Path(path).read_text())\n\n\ndef _mapping_blockers(variant: DraftVariant, store_db: Path) -> list[str]:\n    if variant.store_product_id is None:\n        return [\"store_product_and_variant_not_selected\"]\n    # mode=ro is essential: never create a fresh empty store.db while checking.\n    uri = Path(store_db).resolve().as_uri() + \"?mode=ro\"\n    try:\n        with sqlite3.connect(uri, uri=True) as db:\n            row = db.execute(\"\"\"SELECT p.id, v.product_id, p.active, v.active\n                FROM products p JOIN product_variants v ON v.id=? WHERE p.id=?\"\"\",\n                (variant.store_variant_id, variant.store_product_id)).fetchone()\n    except sqlite3.Error:\n        return [\"store_mapping_unverified\"]\n    if row is None or row[0] != row[1]:\n        return [\"store_variant_does_not_belong_to_product\"]\n    if row[2] or row[3]:\n        return [\"linked_store_product_or_variant_is_active\"]\n    return []\n\n\ndef _current(confirmed: date, expires: date, today: date) -> bool:\n    return confirmed <= today <= expires\n\n\ndef _retail_estimate(cost: Decimal, config: dict) -> Decimal:\n    \"\"\"All-in retail worksheet: shipping is included, not a checkout quote.\"\"\"\n    margin = Decimal(str(config[\"MARGIN_PCT\"]))\n    fee_pct = Decimal(str(config[\"PAYPAL_PCT\"]))\n    fixed = Decimal(str(config[\"PAYPAL_FIXED\"]))\n    ops = Decimal(str(config[\"OPS_FIXED\"]))\n    floor = Decimal(str(config[\"MIN_PRICE\"]))\n    if (not all(x.is_finite() for x in (margin, fee_pct, fixed, ops, floor))\n            or margin < 0 or fee_pct < 0 or margin + fee_pct >= 1\n            or min(fixed, ops, floor) < 0):\n        raise ValueError(\"Invalid pricing assumptions\")\n    raw = max(floor, (cost + fixed + ops) / (1 - margin - fee_pct))\n    # The smallest x.99 price that covers the calculated minimum.\n    return (raw - Decimal(\"0.99\")).to_integral_value(rounding=ROUND_CEILING) + Decimal(\"0.99\")\n\n\ndef catalog_report(catalog: DraftCatalog, store_db: Path = DEFAULT_STORE_DB,\n                   *, today: date | None = None, pricing: dict | None = None) -> dict:\n    from services.pricing import pricing_config\n    today = today or datetime.now(ZoneInfo(\"America/Santiago\")).date()\n    pricing = pricing_config() if pricing is None else pricing\n    rows = []\n    for variant in catalog.variants:\n        blockers = _mapping_blockers(variant, store_db)\n        if variant.mockup_is_placeholder:\n            blockers.append(\"real_product_mockup_not_supplied\")\n        if not variant.sandbox_order_id:\n            blockers.append(\"sandbox_creation_evidence_missing\")\n        if not catalog.requested_countries:\n            blockers.append(\"sales_destinations_not_selected\")\n        destinations = []\n        for country in catalog.requested_countries:\n            quotes = [q for q in variant.cost_quotes if q.country == country and _current(q.confirmed_on, q.valid_until, today)]\n            if not quotes:\n                destinations.append({\"country\": country, \"state\": \"quote_required\", \"retail_estimate_usd\": None})\n                continue\n            for quote in quotes:\n                result = {\"country\": country, \"postal_code\": quote.postal_code,\n                          \"method\": quote.method, \"quantity\": 1,\n                          \"state\": \"fx_required\", \"retail_estimate_usd\": None,\n                          \"all_in_cost_inr\": str(quote.total()),\n                          \"quote_source\": quote.source, \"valid_until\": quote.valid_until.isoformat()}\n                if catalog.fx and _current(catalog.fx.confirmed_on, catalog.fx.valid_until, today):\n                    # Keep full precision until the final displayed USD amount.\n                    usd = quote.total() * catalog.fx.usd_per_inr\n                    try:\n                        estimate = _retail_estimate(usd, pricing)\n                    except (ValueError, ArithmeticError):\n                        result[\"state\"] = \"pricing_configuration_invalid\"\n                    else:\n                        result.update(state=\"worksheet_only\", all_in_cost_usd=str(usd),\n                                      retail_estimate_usd=f\"{estimate:.2f}\",\n                                      fx_source=catalog.fx.source,\n                                      eta_days=[quote.eta_min_days, quote.eta_max_days])\n                destinations.append(result)\n        rows.append({\"key\": variant.key, \"sku\": variant.sku,\n                     \"store_product_id\": variant.store_product_id,\n                     \"store_variant_id\": variant.store_variant_id,\n                     \"sandbox_order_id\": variant.sandbox_order_id,\n                     \"sandbox_reference\": variant.sandbox_reference,\n                     \"blockers\": blockers, \"destinations\": destinations})\n    return {\"environment\": \"sandbox\", \"as_of\": today.isoformat(), \"public_sales_enabled\": False,\n            \"integration_state\": \"draft_only\",\n            \"note\": \"No live API or checkout integration. Quotes apply only to their listed postal code and one unit; they do not establish country-wide shipping coverage.\",\n            \"variants\": rows}\n",
  "server/scripts/qikink_sandbox.py": "#!/usr/bin/env python3\n\"\"\"Sandbox-only Qikink CLI. Plain and DTG printed orders default to a dry run.\"\"\"\nfrom __future__ import annotations\n\nimport argparse\nimport asyncio\nimport json\nimport sys\nfrom pathlib import Path\n\nROOT = Path(__file__).resolve().parents[1]\nsys.path.insert(0, str(ROOT))\n\nfrom dotenv import load_dotenv\nfrom services.qikink import PlainOrder, PrintedOrder, PrintDesign, QikinkError, SandboxClient, SandboxJournal, DEFAULT_JOURNAL\nfrom services.qikink_catalog import DEFAULT_CATALOG, DEFAULT_STORE_DB, load_catalog, catalog_report\n\n\n# Matches the synthetic address of the manually confirmed Sandbox order.\nTEST_ADDRESS = {\n    \"first_name\": \"Sandbox\", \"last_name\": \"Test\", \"address1\": \"Sandbox test address\",\n    \"phone\": \"9876543210\", \"email\": \"sandbox@example.com\", \"city\": \"Coimbatore\",\n    \"zip\": \"641001\", \"province\": \"Tamil Nadu\", \"country_code\": \"IN\",\n}\n\n\ndef parser() -> argparse.ArgumentParser:\n    cli = argparse.ArgumentParser(description=__doc__)\n    cli.add_argument(\"--journal\", type=Path, default=DEFAULT_JOURNAL)\n    commands = cli.add_subparsers(dest=\"command\", required=True)\n    commands.add_parser(\"auth\", help=\"Authenticate only; prints no token\")\n    catalog = commands.add_parser(\"catalog\", help=\"Offline draft mapping/cost report; never publishes products\")\n    catalog.add_argument(\"--file\", type=Path, default=DEFAULT_CATALOG)\n    catalog.add_argument(\"--store-db\", type=Path, default=DEFAULT_STORE_DB)\n    catalog.add_argument(\"--country\", action=\"append\", help=\"Requested ISO country, e.g. US; repeat as needed\")\n    lookup = commands.add_parser(\"lookup\", help=\"Read only; unavailable Sandbox routes are reported\")\n    lookup.add_argument(\"order_id\")\n    history = commands.add_parser(\"status\", help=\"Read the local journal, with no network call\")\n    history.add_argument(\"reference\")\n    for name in (\"plain\", \"printed\", \"remember\"):\n        sub = commands.add_parser(name)\n        sub.add_argument(\"--reference\", required=True, help=\"Reuse the same reference for the same logical order\")\n        sub.add_argument(\"--sku\", default=\"MVnHs-Wh-S\")\n        if name in {\"plain\", \"printed\"}:\n            sub.add_argument(\"--submit-sandbox\", action=\"store_true\", help=\"Actually create one Sandbox order\")\n        else:\n            sub.add_argument(\"--order-id\", required=True, help=\"Manually confirmed ID of an existing plain Sandbox test\")\n        if name == \"printed\":\n            sub.add_argument(\"--design-code\", help=\"Defaults to reference + _d; reuse the same code for the same artwork\")\n            sub.add_argument(\"--design-url\", default=\"https://thebookswanderer.com/assets/logo.png\")\n            sub.add_argument(\"--mockup-url\", default=\"https://thebookswanderer.com/assets/logo.png\",\n                             help=\"Sandbox placeholder by default; not a product mockup for sale\")\n            sub.add_argument(\"--width\", type=float, default=2)\n            sub.add_argument(\"--height\", type=float, default=2)\n    return cli\n\n\nasync def run(args) -> dict:\n    if args.command == \"catalog\":\n        catalog = load_catalog(args.file)\n        if args.country is not None:\n            catalog = type(catalog).model_validate(catalog.model_dump() | {\"requested_countries\": args.country})\n        return catalog_report(catalog, args.store_db)\n    order = None\n    if args.command in {\"plain\", \"printed\", \"remember\"}:\n        values = dict(reference=args.reference, sku=args.sku, shipping_address=TEST_ADDRESS)\n        if args.command == \"printed\":\n            order = PrintedOrder(**values, design=PrintDesign(\n                design_code=args.design_code or args.reference + \"_d\", width_inches=args.width, height_inches=args.height,\n                design_link=args.design_url, mockup_link=args.mockup_url))\n        else:\n            order = PlainOrder(**values)\n        if args.command in {\"plain\", \"printed\"} and not args.submit_sandbox:\n            return {\"environment\": \"sandbox\", \"dry_run\": True, \"payload\": order.payload()}\n    journal = SandboxJournal(args.journal)\n    async with SandboxClient.from_env(journal) as client:\n        if args.command == \"auth\":\n            await client.authenticate()\n            return {\"environment\": \"sandbox\", \"authenticated\": True}\n        if args.command == \"plain\":\n            return {\"environment\": \"sandbox\", **await client.create_plain_order(order)}\n        if args.command == \"printed\":\n            return {\"environment\": \"sandbox\", **await client.create_printed_order(order)}\n        if args.command == \"remember\":\n            return {\"environment\": \"sandbox\", \"source\": \"operator_confirmed\",\n                    \"reference\": order.reference, **client.remember_existing(order, args.order_id)}\n        if args.command == \"status\":\n            return {\"environment\": \"sandbox\", \"record\": journal.get(client.account, args.reference)}\n        return {\"environment\": \"sandbox\", **await client.lookup(args.order_id)}\n\n\ndef main() -> int:\n    args = parser().parse_args()\n    load_dotenv(ROOT / \".env\")\n    try:\n        result = asyncio.run(run(args))\n    except QikinkError as exc:\n        print(json.dumps({\"environment\": \"sandbox\", \"error\": str(exc), \"error_type\": type(exc).__name__}))\n        return 1\n    except (Exception, KeyboardInterrupt) as exc:\n        # Validation errors, transport URLs, and SQLite messages can expose data.\n        print(json.dumps({\"environment\": \"sandbox\", \"error_type\": type(exc).__name__,\n                          \"detail\": \"Check failed; details withheld. Inspect the journal before retrying submission.\"}))\n        return 1\n    print(json.dumps(result, indent=2))\n    return 2 if result.get(\"state\") == \"unverified\" else 0\n\n\nif __name__ == \"__main__\":\n    sys.exit(main())\n",
  "server/tests/test_qikink.py": "\"\"\"Qikink Sandbox contract and duplicate protection; all HTTP calls are mocked.\"\"\"\nimport asyncio\nfrom io import BytesIO\nimport json\nimport os\nimport sys\nimport tempfile\nimport unittest\nfrom pathlib import Path\nfrom unittest.mock import patch\n\nimport httpx\nfrom pydantic import ValidationError\nfrom PIL import Image\n\nsys.path.insert(0, str(Path(__file__).resolve().parents[1]))\nfrom services.qikink import (DuplicateBlocked, OutcomeUnknown, PlainOrder, QikinkError,\n                              SandboxClient, SandboxJournal, PrintedOrder, PrintDesign)\n\nADDRESS = {\n    \"first_name\": \"Sandbox\", \"last_name\": \"Test\", \"address1\": \"Sandbox test address\",\n    \"phone\": \"9876543210\", \"email\": \"sandbox@example.com\", \"city\": \"Coimbatore\",\n    \"zip\": \"641001\", \"province\": \"Tamil Nadu\", \"country_code\": \"IN\",\n}\n\n\ndef order(reference=\"tbw_test\", **extra):\n    return PlainOrder(reference=reference, sku=\"MVnHs-Wh-S\", shipping_address=ADDRESS, **extra)\n\n\nclass QikinkTests(unittest.IsolatedAsyncioTestCase):\n    def setUp(self):\n        self.tmp = tempfile.TemporaryDirectory()\n        self.addCleanup(self.tmp.cleanup)\n        self.path = Path(self.tmp.name) / \"sandbox.db\"\n        self.journal = SandboxJournal(self.path)\n        self.calls = []\n        env = patch.dict(os.environ, {\"QIKINK_ENV\": \"sandbox\", \"QIKINK_BASE_URL\": \"https://api.qikink.com\"})\n        env.start()\n        self.addCleanup(env.stop)\n\n    def client(self, handler=None):\n        async def respond(request):\n            self.assertEqual(request.url.scheme, \"https\")\n            self.assertIn(request.url.host, {\"sandbox.qikink.com\", \"thebookswanderer.com\"})\n            self.calls.append(request.url.path)\n            if handler:\n                reply = handler(request)\n                return await reply if asyncio.iscoroutine(reply) else reply\n            if request.url.path == \"/api/token\":\n                self.assertIn(b\"ClientId=test-client\", request.content)\n                self.assertIn(b\"client_secret=test-secret\", request.content)\n                return httpx.Response(200, json={\"Accesstoken\": \"private-token\", \"expires_in\": 3600})\n            self.assertEqual(request.url.path, \"/api/order/create\")\n            payload = json.loads(request.content)\n            self.assertEqual(request.headers[\"Accesstoken\"], \"private-token\")\n            self.assertEqual(payload[\"gateway\"], \"Prepaid\")\n            self.assertEqual(payload[\"line_items\"][0][\"print_type_id\"], \"1\")\n            self.assertNotIn(\"designs\", payload[\"line_items\"][0])\n            return httpx.Response(200, json={\"status_code\": \"200\", \"order_id\": 24616032})\n        return SandboxClient(\"test-client\", \"test-secret\", self.journal, transport=httpx.MockTransport(respond))\n\n    async def test_creation_survives_client_and_journal_restart_without_resending(self):\n        async with self.client() as client:\n            result = await client.create_plain_order(order())\n        self.assertEqual(result[\"order_id\"], \"24616032\")\n        self.assertFalse(result[\"cached\"])\n        self.journal = SandboxJournal(self.path)\n        async with self.client() as client:\n            again = await client.create_plain_order(order())\n        self.assertTrue(again[\"cached\"])\n        self.assertEqual(self.calls, [\"/api/token\", \"/api/order/create\"])\n        saved = self.path.read_bytes()\n        for secret in (b\"private-token\", b\"test-secret\", b\"sandbox@example.com\", b\"Sandbox test address\"):\n            self.assertNotIn(secret, saved)\n\n    async def test_changed_payload_cannot_reuse_reference(self):\n        async with self.client() as client:\n            await client.create_plain_order(order())\n            with self.assertRaises(DuplicateBlocked):\n                await client.create_plain_order(order(quantity=2))\n        self.assertEqual(self.calls.count(\"/api/order/create\"), 1)\n\n    async def test_timeout_is_persistently_uncertain_without_automatic_retry(self):\n        def respond(request):\n            if request.url.path == \"/api/token\":\n                return httpx.Response(200, json={\"Accesstoken\": \"private-token\"})\n            raise httpx.ReadTimeout(\"private-token test-secret\")\n        async with self.client(respond) as client:\n            with self.assertRaises(OutcomeUnknown) as caught:\n                await client.create_plain_order(order())\n            self.assertNotIn(\"private-token\", str(caught.exception))\n            self.assertEqual(self.journal.get(client.account, \"tbw_test\")[\"state\"], \"uncertain\")\n        self.journal = SandboxJournal(self.path)\n        async with self.client() as client:\n            with self.assertRaises(DuplicateBlocked):\n                await client.create_plain_order(order())\n        self.assertEqual(self.calls.count(\"/api/order/create\"), 1)\n\n    async def test_validation_rejection_stays_blocked_and_does_not_disclose_body(self):\n        def respond(request):\n            if request.url.path == \"/api/token\":\n                return httpx.Response(200, json={\"Accesstoken\": \"private-token\"})\n            return httpx.Response(400, json={\"error\": \"test-secret private-token\"})\n        async with self.client(respond) as client:\n            with self.assertRaises(QikinkError) as caught:\n                await client.create_plain_order(order())\n            self.assertNotIn(\"test-secret\", str(caught.exception))\n            self.assertEqual(self.journal.get(client.account, \"tbw_test\")[\"state\"], \"rejected\")\n            with self.assertRaises(DuplicateBlocked):\n                await client.create_plain_order(order())\n        self.assertEqual(self.calls.count(\"/api/order/create\"), 1)\n\n    async def test_ambiguous_creation_responses_are_not_retried(self):\n        for index, response in enumerate([\n            httpx.Response(500), httpx.Response(302, headers={\"Location\": \"https://api.qikink.com\"}),\n            httpx.Response(200, text=\"not json\"), httpx.Response(200, json={\"status_code\": \"200\"}),\n            httpx.Response(200, json={\"status_code\": \"400\", \"order_id\": 123}),\n            httpx.Response(200, json={\"status_code\": \"200\", \"order_id\": True}),\n        ]):\n            def respond(request):\n                return (httpx.Response(200, json={\"Accesstoken\": \"private-token\"})\n                        if request.url.path == \"/api/token\" else response)\n            async with self.client(respond) as client:\n                with self.assertRaises(OutcomeUnknown):\n                    await client.create_plain_order(order(f\"case_{index}\"))\n                with self.assertRaises(DuplicateBlocked):\n                    await client.create_plain_order(order(f\"case_{index}\"))\n        self.assertEqual(self.calls.count(\"/api/order/create\"), 6)\n\n    async def test_failure_before_submission_can_be_safely_retried(self):\n        def respond(request):\n            return httpx.Response(200, json={\"Accesstoken\": \"\", \"error\": \"test-secret\"})\n        async with self.client(respond) as client:\n            with self.assertRaises(QikinkError):\n                await client.create_plain_order(order())\n            self.assertEqual(self.journal.get(client.account, \"tbw_test\")[\"state\"], \"not_sent\")\n        async with self.client() as client:\n            self.assertEqual((await client.create_plain_order(order()))[\"state\"], \"created\")\n        self.assertEqual(self.calls.count(\"/api/order/create\"), 1)\n\n    async def test_concurrent_clients_share_atomic_reservations(self):\n        entered = asyncio.Event()\n        release = asyncio.Event()\n        async def respond(request):\n            if request.url.path == \"/api/token\":\n                return httpx.Response(200, json={\"Accesstoken\": \"private-token\"})\n            entered.set()\n            await release.wait()\n            return httpx.Response(200, json={\"status_code\": \"200\", \"order_id\": 123})\n        async with self.client(respond) as first, self.client() as second:\n            second.journal = SandboxJournal(self.path)\n            pending = asyncio.create_task(first.create_plain_order(order()))\n            await asyncio.wait_for(entered.wait(), timeout=2)\n            try:\n                with self.assertRaises(DuplicateBlocked):\n                    await second.create_plain_order(order())\n            finally:\n                release.set()\n                await pending\n        self.assertEqual(self.calls.count(\"/api/order/create\"), 1)\n\n    async def test_token_is_reused_until_expiry(self):\n        async with self.client() as client:\n            await client.create_plain_order(order(\"one\"))\n            await client.create_plain_order(order(\"two\"))\n            self.assertEqual(self.calls.count(\"/api/token\"), 1)\n            client._expires = 0\n            await client.create_plain_order(order(\"three\"))\n        self.assertEqual(self.calls.count(\"/api/token\"), 2)\n\n    async def test_manual_existing_order_blocks_submission_without_network(self):\n        async with self.client() as client:\n            client.remember_existing(order(\"tbw_9ba7265277\"), \"24616032\")\n            result = await client.create_plain_order(order(\"tbw_9ba7265277\"))\n            self.assertTrue(result[\"cached\"])\n            with self.assertRaises(DuplicateBlocked):\n                client.remember_existing(order(\"tbw_9ba7265277\"), \"999\")\n        self.assertEqual(self.calls, [])\n\n    async def test_read_failure_preserves_confirmed_creation(self):\n        async with self.client() as client:\n            client.remember_existing(order(), \"24616032\")\n            account = client.account\n        def respond(request):\n            if request.url.path == \"/api/token\":\n                return httpx.Response(200, json={\"Accesstoken\": \"private-token\"})\n            return httpx.Response(404 if request.url.path.endswith(\"list\") else 500)\n        async with self.client(respond) as client:\n            result = await client.lookup(\"24616032\")\n        self.assertEqual(result[\"state\"], \"unverified\")\n        self.assertEqual([a[\"http_status\"] for a in result[\"attempts\"]], [404, 500])\n        self.assertEqual(self.journal.get(account, \"tbw_test\")[\"state\"], \"created\")\n        self.assertNotIn(\"/api/order/create\", self.calls)\n\n    async def test_http_200_alone_does_not_confirm_order_lookup(self):\n        for body in ({\"success\": True, \"data\": []}, {\"data\": [{\"order_id\": \"999\"}]},\n                     {\"success\": False, \"data\": [{\"order_id\": \"24616032\"}]}):\n            def respond(request):\n                return (httpx.Response(200, json={\"Accesstoken\": \"private-token\"})\n                        if request.url.path == \"/api/token\" else httpx.Response(200, json=body))\n            async with self.client(respond) as client:\n                self.assertEqual((await client.lookup(\"24616032\"))[\"state\"], \"unverified\")\n\n    async def test_lookup_requires_matching_order_id(self):\n        def respond(request):\n            return (httpx.Response(200, json={\"Accesstoken\": \"private-token\"})\n                    if request.url.path == \"/api/token\" else\n                    httpx.Response(200, json={\"success\": True, \"data\": [{\"order_id\": 24616032}]}))\n        async with self.client(respond) as client:\n            self.assertEqual((await client.lookup(\"24616032\"))[\"state\"], \"found\")\n        self.assertNotIn(\"/api/order/create\", self.calls)\n\n    async def test_payload_is_snapshotted_before_authentication(self):\n        original = order()\n        async def respond(request):\n            if request.url.path == \"/api/token\":\n                original.shipping_address.city = \"Changed during authentication\"\n                return httpx.Response(200, json={\"Accesstoken\": \"private-token\"})\n            self.assertEqual(json.loads(request.content)[\"shipping_address\"][\"city\"], \"Coimbatore\")\n            return httpx.Response(200, json={\"status_code\": \"200\", \"order_id\": 1})\n        async with self.client(respond) as client:\n            await client.create_plain_order(original)\n\n    def test_live_mode_is_refused(self):\n        with patch.dict(os.environ, {\"QIKINK_ENV\": \"live\"}):\n            with self.assertRaises(QikinkError):\n                self.client()\n\n    def test_invalid_orders_fail_before_network(self):\n        for change in ({\"reference\": \"TOO-LONG-REFERENCE\"}, {\"quantity\": 0}, {\"quantity\": True},\n                       {\"quantity\": 101}, {\"price\": \"NaN\"}, {\"total_order_value\": \"-1\"}):\n            data = order().model_dump() | change\n            with self.assertRaises(ValidationError):\n                PlainOrder.model_validate(data)\n        self.assertEqual(self.calls, [])\n\n\n    def printed_order(self, reference=\"tbw_print001\", **design_changes):\n        values = {\n            \"design_code\": \"tbw_logo_test01\",\n            \"design_link\": \"https://thebookswanderer.com/assets/logo.png\",\n            \"mockup_link\": \"https://thebookswanderer.com/assets/logo.png\",\n        } | design_changes\n        return PrintedOrder(**order(reference).model_dump(), design=PrintDesign(**values))\n\n    def image_response(self):\n        buffer = BytesIO()\n        Image.new(\"RGB\", (2, 2), \"white\").save(buffer, format=\"PNG\")\n        return httpx.Response(200, headers={\"Content-Type\": \"image/png\"}, content=buffer.getvalue())\n\n    def printed_response(self, request):\n        if request.url.host == \"thebookswanderer.com\":\n            self.assertEqual(request.method, \"GET\")\n            self.assertNotIn(\"ClientId\", request.headers)\n            self.assertNotIn(\"Accesstoken\", request.headers)\n            return self.image_response()\n        if request.url.path == \"/api/token\":\n            return httpx.Response(200, json={\"Accesstoken\": \"private-token\"})\n        payload = json.loads(request.content)\n        line = payload[\"line_items\"][0]\n        self.assertEqual(line[\"print_type_id\"], \"1\")\n        self.assertEqual(line[\"search_from_my_products\"], 0)\n        self.assertEqual(line[\"designs\"][0][\"width_inches\"], 2)\n        self.assertEqual(line[\"designs\"][0][\"height_inches\"], 2)\n        self.assertEqual(line[\"designs\"][0][\"placement_sku\"], \"fr\")\n        self.assertIn(\"design_link\", line[\"designs\"][0])\n        self.assertNotIn(\"design_url\", line[\"designs\"][0])\n        self.assertNotIn(\"add_ons\", payload)\n        return httpx.Response(200, json={\"status_code\": \"200\", \"order_id\": 24616033})\n\n    async def test_printed_preflight_then_create_and_cached_retry(self):\n        async with self.client(self.printed_response) as client:\n            result = await client.create_printed_order(self.printed_order())\n            self.assertEqual(result[\"order_id\"], \"24616033\")\n            self.assertEqual(self.calls, [\"/assets/logo.png\", \"/api/token\", \"/api/order/create\"])\n            cached = await client.create_printed_order(self.printed_order())\n            self.assertTrue(cached[\"cached\"])\n            self.assertEqual(len(self.calls), 3)\n            with self.assertRaises(DuplicateBlocked):\n                await client.create_printed_order(self.printed_order(width_inches=3))\n        saved = self.path.read_bytes()\n        self.assertNotIn(b\"https://thebookswanderer.com/assets/logo.png\", saved)\n\n    async def test_printed_payload_cannot_reuse_plain_reference(self):\n        async with self.client(self.printed_response) as client:\n            client.remember_existing(order(), \"24616032\")\n            with self.assertRaises(DuplicateBlocked):\n                await client.create_printed_order(self.printed_order(\"tbw_test\"))\n        self.assertEqual(self.calls, [])\n\n    async def test_bad_artwork_blocks_auth_and_creation_but_can_be_fixed(self):\n        bad_responses = [\n            httpx.Response(404),\n            httpx.Response(302, headers={\"Location\": \"https://api.qikink.com\"}),\n            httpx.Response(200, headers={\"Content-Type\": \"text/html\"}, text=\"<html>error</html>\"),\n            httpx.Response(200, headers={\"Content-Type\": \"image/png\"}, content=b\"not an image\"),\n        ]\n        for index, bad_response in enumerate(bad_responses):\n            def respond(request):\n                return bad_response\n            candidate = self.printed_order(f\"bad_image_{index}\")\n            async with self.client(respond) as client:\n                with self.assertRaises(QikinkError):\n                    await client.create_printed_order(candidate)\n                self.assertEqual(self.journal.get(client.account, candidate.reference)[\"state\"], \"not_sent\")\n        self.assertNotIn(\"/api/token\", self.calls)\n        self.assertNotIn(\"/api/order/create\", self.calls)\n        async with self.client(self.printed_response) as client:\n            self.assertEqual((await client.create_printed_order(candidate))[\"state\"], \"created\")\n\n    async def test_large_artwork_is_not_submitted(self):\n        def respond(request):\n            return httpx.Response(200, headers={\"Content-Type\": \"image/png\"}, content=b\"x\" * (4 * 1024 * 1024 + 1))\n        async with self.client(respond) as client:\n            with self.assertRaises(QikinkError):\n                await client.create_printed_order(self.printed_order())\n        self.assertNotIn(\"/api/token\", self.calls)\n\n    async def test_distinct_mockup_url_is_checked_without_credentials(self):\n        async with self.client(self.printed_response) as client:\n            await client.create_printed_order(self.printed_order(mockup_link=\"https://thebookswanderer.com/assets/og-default.jpg\"))\n        self.assertEqual(self.calls[:2], [\"/assets/logo.png\", \"/assets/og-default.jpg\"])\n\n    async def test_printed_timeout_is_not_retried(self):\n        def respond(request):\n            if request.url.path == \"/api/order/create\":\n                raise httpx.ReadTimeout(\"private-token\")\n            return self.printed_response(request)\n        async with self.client(respond) as client:\n            with self.assertRaises(OutcomeUnknown):\n                await client.create_printed_order(self.printed_order())\n            with self.assertRaises(DuplicateBlocked):\n                await client.create_printed_order(self.printed_order())\n        self.assertEqual(self.calls.count(\"/api/order/create\"), 1)\n\n    def test_invalid_printed_designs_are_refused_locally(self):\n        for change in ({\"design_code\": \"\"}, {\"design_code\": \"x\" * 21}, {\"width_inches\": 0},\n                       {\"width_inches\": 17}, {\"height_inches\": 21}, {\"height_inches\": float(\"nan\")},\n                       {\"placement_sku\": \"bad\"}, {\"design_link\": \"http://thebookswanderer.com/a.png\"},\n                       {\"mockup_link\": \"https://127.0.0.1/a.png\"},\n                       {\"design_link\": \"https://thebookswanderer.com/a.png?token=secret\"},\n                       {\"design_link\": \"https://user:pass@thebookswanderer.com/a.png\"}):\n            with self.assertRaises(ValidationError):\n                self.printed_order(**change)\n        self.assertEqual(self.calls, [])\n\nif __name__ == \"__main__\":\n    unittest.main()\n",
  "server/tests/test_qikink_catalog.py": "\"\"\"Offline staging: missing costs stay unknown; no store writes or remote calls.\"\"\"\nfrom datetime import date\nfrom decimal import Decimal\nimport hashlib\nfrom pathlib import Path\nimport sqlite3\nimport sys\nimport tempfile\nimport unittest\nfrom unittest.mock import patch\n\nfrom pydantic import ValidationError\n\nROOT = Path(__file__).resolve().parents[1]\nsys.path.insert(0, str(ROOT))\nsys.path.insert(0, str(ROOT / \"scripts\"))\nfrom services.qikink_catalog import DraftCatalog, catalog_report, load_catalog\nfrom services.qikink import SandboxClient\nimport qikink_sandbox as cli\n\nTODAY = date(2026, 10, 19)\nPRICING = {\"MARGIN_PCT\": \"0.40\", \"PAYPAL_PCT\": \"0.0349\", \"PAYPAL_FIXED\": \"0.49\",\n           \"OPS_FIXED\": \"0.35\", \"MIN_PRICE\": \"6.99\"}\n\n\nclass CatalogTests(unittest.IsolatedAsyncioTestCase):\n    def setUp(self):\n        self.temp = tempfile.TemporaryDirectory()\n        self.addCleanup(self.temp.cleanup)\n        self.db = Path(self.temp.name) / \"store.db\"\n        self.data = load_catalog().model_dump(mode=\"json\")\n\n    def quote(self, **changes):\n        return dict(sku=\"MVnHs-Wh-S\", design=self.data[\"variants\"][0][\"design\"], quantity=1, country=\"IN\", postal_code=\"641001\",\n                    method=\"Test quote method\", eta_min_days=5, eta_max_days=10,\n                    currency=\"INR\", product=\"200\", printing=\"100\", packaging=\"10\",\n                    tax=\"30\", shipping=\"60\", other=\"0\", source=\"Operator supplied test fixture, NOT a real quote\",\n                    confirmed_on=\"2026-10-18\", valid_until=\"2026-10-20\") | changes\n\n    def fx(self, **changes):\n        return dict(currency_pair=\"INR_USD\", usd_per_inr=\"0.012\", source=\"Test fixture, NOT a live FX rate\",\n                    confirmed_on=\"2026-10-18\", valid_until=\"2026-10-20\") | changes\n\n    def report(self):\n        return catalog_report(DraftCatalog.model_validate(self.data), self.db, today=TODAY, pricing=PRICING)\n\n    def test_draft_uses_confirmed_design_order_without_inventing_costs_or_mapping(self):\n        result = self.report()\n        self.assertFalse(result[\"public_sales_enabled\"])\n        row = result[\"variants\"][0]\n        self.assertEqual(row[\"sandbox_order_id\"], \"24620736\")\n        self.assertIsNone(row[\"store_product_id\"])\n        self.assertIn(\"sales_destinations_not_selected\", row[\"blockers\"])\n        self.assertIn(\"real_product_mockup_not_supplied\", row[\"blockers\"])\n        self.assertFalse(self.db.exists())\n\n    def test_requested_destinations_without_quotes_are_unknown_not_free(self):\n        self.data[\"requested_countries\"] = [\"US\", \"CL\", \"IN\"]\n        rows = self.report()[\"variants\"][0][\"destinations\"]\n        self.assertEqual(len(rows), 3)\n        self.assertTrue(all(row[\"state\"] == \"quote_required\" and row[\"retail_estimate_usd\"] is None for row in rows))\n\n    def test_complete_quote_and_fx_calculate_destination_specific_all_in_estimate(self):\n        self.data[\"requested_countries\"] = [\"IN\"]\n        self.data[\"variants\"][0][\"cost_quotes\"] = [self.quote()]\n        self.data[\"fx\"] = self.fx()\n        result = self.report()\n        row = result[\"variants\"][0][\"destinations\"][0]\n        self.assertEqual(Decimal(row[\"all_in_cost_inr\"]), Decimal(\"400\"))\n        self.assertEqual(Decimal(row[\"all_in_cost_usd\"]), Decimal(\"4.8\"))\n        self.assertEqual(row[\"retail_estimate_usd\"], \"9.99\")\n        self.assertEqual(row[\"postal_code\"], \"641001\")\n        self.assertEqual(row[\"quantity\"], 1)\n        self.assertEqual(row[\"state\"], \"worksheet_only\")\n        self.assertFalse(result[\"public_sales_enabled\"])\n\n    def test_expired_or_future_quote_does_not_price_or_enable_destination(self):\n        self.data[\"requested_countries\"] = [\"IN\"]\n        for dates in ({\"confirmed_on\": \"2026-10-01\", \"valid_until\": \"2026-10-18\"},\n                      {\"confirmed_on\": \"2026-10-20\", \"valid_until\": \"2026-10-21\"}):\n            self.data[\"variants\"][0][\"cost_quotes\"] = [self.quote(**dates)]\n            self.assertEqual(self.report()[\"variants\"][0][\"destinations\"][0][\"state\"], \"quote_required\")\n\n    def test_fx_is_required_current_and_correct_direction(self):\n        self.data[\"requested_countries\"] = [\"IN\"]\n        self.data[\"variants\"][0][\"cost_quotes\"] = [self.quote()]\n        for fx in (None, self.fx(confirmed_on=\"2026-10-01\", valid_until=\"2026-10-18\")):\n            self.data[\"fx\"] = fx\n            self.assertEqual(self.report()[\"variants\"][0][\"destinations\"][0][\"state\"], \"fx_required\")\n        self.data[\"fx\"] = self.fx(currency_pair=\"USD_INR\")\n        with self.assertRaises(ValidationError):\n            self.report()\n\n    def test_incomplete_nonfinite_wrong_sku_or_wrong_quantity_quotes_are_rejected(self):\n        for change in ({\"sku\": \"OTHER-SKU\"}, {\"design\": self.data[\"variants\"][0][\"design\"] | {\"width_inches\": 3}}, {\"quantity\": 2}, {\"shipping\": \"NaN\"},\n                       {\"product\": \"-1\"}, {\"eta_min_days\": 15, \"eta_max_days\": 3}):\n            self.data[\"variants\"][0][\"cost_quotes\"] = [self.quote(**change)]\n            with self.assertRaises(ValidationError):\n                self.report()\n        incomplete = self.quote()\n        del incomplete[\"tax\"]\n        self.data[\"variants\"][0][\"cost_quotes\"] = [incomplete]\n        with self.assertRaises(ValidationError):\n            self.report()\n\n    def test_wrong_country_quote_does_not_enable_other_countries(self):\n        self.data[\"requested_countries\"] = [\"US\"]\n        self.data[\"variants\"][0][\"cost_quotes\"] = [self.quote()]\n        self.data[\"fx\"] = self.fx()\n        self.assertEqual(self.report()[\"variants\"][0][\"destinations\"][0][\"state\"], \"quote_required\")\n\n    def make_store(self):\n        with sqlite3.connect(self.db) as db:\n            db.executescript('''CREATE TABLE products (id INTEGER, active INTEGER);\n                CREATE TABLE product_variants (id INTEGER, product_id INTEGER, active INTEGER);\n                INSERT INTO products VALUES (1,0), (2,1);\n                INSERT INTO product_variants VALUES (10,1,0), (20,2,1);''')\n        self.data[\"variants\"][0].update(store_product_id=1, store_variant_id=10)\n\n    def test_mapping_is_read_only_and_validates_variant_parent(self):\n        self.make_store()\n        before = hashlib.sha256(self.db.read_bytes()).hexdigest()\n        self.assertNotIn(\"store_mapping_unverified\", self.report()[\"variants\"][0][\"blockers\"])\n        self.data[\"variants\"][0][\"store_variant_id\"] = 20\n        self.assertIn(\"store_variant_does_not_belong_to_product\", self.report()[\"variants\"][0][\"blockers\"])\n        self.assertEqual(hashlib.sha256(self.db.read_bytes()).hexdigest(), before)\n\n    def test_active_product_or_variant_is_blocked_for_staging(self):\n        self.make_store()\n        self.data[\"variants\"][0].update(store_product_id=2, store_variant_id=20)\n        self.assertIn(\"linked_store_product_or_variant_is_active\", self.report()[\"variants\"][0][\"blockers\"])\n\n    def test_missing_database_is_not_created_by_lookup(self):\n        self.data[\"variants\"][0].update(store_product_id=1, store_variant_id=10)\n        self.assertIn(\"store_mapping_unverified\", self.report()[\"variants\"][0][\"blockers\"])\n        self.assertFalse(self.db.exists())\n\n    def test_invalid_pricing_assumptions_never_produce_estimate(self):\n        self.data[\"requested_countries\"] = [\"IN\"]\n        self.data[\"variants\"][0][\"cost_quotes\"] = [self.quote()]\n        self.data[\"fx\"] = self.fx()\n        result = catalog_report(DraftCatalog.model_validate(self.data), self.db, today=TODAY,\n                                pricing=PRICING | {\"MARGIN_PCT\": \"0.99\"})\n        row = result[\"variants\"][0][\"destinations\"][0]\n        self.assertEqual(row[\"state\"], \"pricing_configuration_invalid\")\n        self.assertIsNone(row[\"retail_estimate_usd\"])\n\n    def test_duplicates_live_mode_and_public_enable_flags_are_rejected(self):\n        for change in ({\"environment\": \"live\"}, {\"public_enabled\": True},\n                       {\"requested_countries\": [\"IN\", \"IN\"]},\n                       {\"variants\": self.data[\"variants\"] * 2}):\n            with self.assertRaises(ValidationError):\n                DraftCatalog.model_validate(self.data | change)\n\n    async def test_catalog_cli_needs_no_credentials_journal_or_network(self):\n        args = cli.parser().parse_args([\"catalog\", \"--country\", \"US\", \"--store-db\", str(self.db)])\n        with patch.object(SandboxClient, \"from_env\", side_effect=AssertionError(\"No HTTP client allowed\")), \\\n             patch.object(cli, \"SandboxJournal\", side_effect=AssertionError(\"No journal writes allowed\")):\n            result = await cli.run(args)\n        self.assertEqual(result[\"variants\"][0][\"destinations\"][0][\"state\"], \"quote_required\")\n        self.assertFalse(self.db.exists())\n\n\nif __name__ == \"__main__\":\n    unittest.main()\n",
  "server/config/qikink_sandbox_catalog.json": "{\n  \"version\": 1,\n  \"environment\": \"sandbox\",\n  \"requested_countries\": [],\n  \"variants\": [\n    {\n      \"key\": \"tbw-logo-dtg-sandbox\",\n      \"title\": \"The Books Wanderer — logo DTG (Sandbox)\",\n      \"store_product_id\": null,\n      \"store_variant_id\": null,\n      \"sku\": \"MVnHs-Wh-S\",\n      \"design\": {\n        \"design_code\": \"tbw_print001_d\",\n        \"width_inches\": 2,\n        \"height_inches\": 2,\n        \"placement_sku\": \"fr\",\n        \"design_link\": \"https://thebookswanderer.com/assets/logo.png\",\n        \"mockup_link\": \"https://thebookswanderer.com/assets/logo.png\"\n      },\n      \"mockup_is_placeholder\": true,\n      \"sandbox_order_id\": \"24620736\",\n      \"sandbox_reference\": \"tbw_print001\",\n      \"cost_quotes\": []\n    }\n  ],\n  \"fx\": null\n}\n",
  "server/docs/QIKINK_SANDBOX.md": "# Qikink Sandbox backend\n\nThis client implements India plain-product and fully specified DTG printed\nSandbox test flows. It has no checkout hooks, production host selector, wallet\nendpoint, payment capture, artwork upload, or automatic retry of order creation.\nExisting store behavior is unchanged. Live fulfillment needs a separate integration.\n\nReference: https://documenter.getpostman.com/view/26157218/2sBYAysUHS\nThe supplied PDF documents plain products with print_type_id=1 and no designs.\nIt also warns that Get Order is unavailable in Sandbox. The observed routes\nreturned 404 (/api/order/list) and 500 (/api/order).\n\n## Configuration\n\nUse the existing server/.env (never commit credentials):\n\n```dotenv\nQIKINK_ENV=sandbox\nQIKINK_SANDBOX_CLIENT_ID=...\nQIKINK_SANDBOX_CLIENT_SECRET=...\n```\n\nQIKINK_ENV defaults to sandbox; any other value is refused. There is no live URL\nconfiguration: calls always use https://sandbox.qikink.com, with redirects off.\nThe CLI reads server/.env without replacing already exported variables. Run it\nas the same Unix user using the same persistent journal each time. On the VPS,\nthe app service runs as www-data; use that ownership for the journal if running\nscripts as root first. No service restart is needed for standalone CLI commands.\n\n## Commands (from server/)\n\n```bash\n.venv/bin/python scripts/qikink_sandbox.py auth\n.venv/bin/python scripts/qikink_sandbox.py plain --reference tbw_test001\n# Above is a dry run, without network calls or order creation.\n# Explicit submission, ONLY when a new Sandbox order is wanted:\n.venv/bin/python scripts/qikink_sandbox.py plain --reference tbw_test001 --submit-sandbox\n.venv/bin/python scripts/qikink_sandbox.py lookup 24616032\n.venv/bin/python scripts/qikink_sandbox.py status tbw_test001\n```\n\nCLI plain defaults match the successfully tested SKU MVnHs-Wh-S, quantity 1,\nvalue 1, Prepaid, no design, synthetic India address. These are test values, not\npricing or customer data. `lookup` returns exit code 2 for an unverified read;\nthis never changes a confirmed creation into a failure or creates a replacement.\nExit code 1 indicates a failed command, 0 a completed command or dry run.\n\n### Preserve the already created order (no API call)\n\nThe operator confirmed a successful response for reference tbw_9ba7265277,\norder ID 24616032. Register that exact plain test payload in the local journal:\n\n```bash\n.venv/bin/python scripts/qikink_sandbox.py remember --reference tbw_9ba7265277 --order-id 24616032\n.venv/bin/python scripts/qikink_sandbox.py status tbw_9ba7265277\n```\n\n`remember` is a local assertion by the operator, not remote verification. It\naccepts only this CLI's plain test payload (including --sku if specified), and\nrefuses to replace a pending/uncertain record or an existing different ID. Do not\nuse it for a different payload or account. It does not reserve a remote reference.\n\n## Printed Sandbox test (DTG)\n\n```bash\n.venv/bin/python scripts/qikink_sandbox.py printed --reference tbw_print001\n# Above: dry run, no network. Explicitly submit ONE test when wanted:\n.venv/bin/python scripts/qikink_sandbox.py printed --reference tbw_print001 --submit-sandbox\n.venv/bin/python scripts/qikink_sandbox.py status tbw_print001\n```\n\nUses the same catalog SKU MVnHs-Wh-S, print_type_id=1 (DTG), quantity/value 1,\nPrepaid and the synthetic India address. Adds one front design, 2 x 2 inches,\nusing https://thebookswanderer.com/assets/logo.png. This existing store logo\nis 512 x 512 pixels (256 pixels/inch at 2 inches). The mockup URL deliberately\nuses the SAME logo as a Sandbox technical placeholder: it is not a product mockup,\nproduct listing or evidence that Qikink printed anything. No image is published\nor changed by this command. SKU/DTG compatibility still needs remote validation.\n\nThe design code defaults to the reference plus _d (tbw_print001_d). Keep it\nstable for retries of that order; use a new code for different artwork, since\nQikink may reuse an existing design code. No fields are left blank. Supports\n--sku, --design-code, --design-url, --mockup-url, --width and --height.\n\nBefore authentication or creation, new printed submissions fetch each distinct\nimage URL WITHOUT Qikink credentials. Only HTTPS store-domain URLs with no query,\nfragment, credentials or custom port are accepted. Responses must be HTTP 200,\nno redirect, image/png or image/jpeg, at most 4 MiB, and verifiable PNG/JPEG\ncontent up to 40 million pixels. A preflight failure records not_sent, permitting\na retry with the same payload after the hosting problem is fixed. It does not\nprove Qikink can fetch the file from its own network.\n\nWidths/heights must be positive and at most 16 x 20 inches (DTG); new design codes\nare limited to 20 characters. Printed payloads share the same journal as plain\norders, so a plain reference cannot accidentally be reused for a printed order.\n\n## Duplicate protection and recovery\n\nThe independent SQLite file server/data/qikink_sandbox.db stores account hashes,\nreferences, payload hashes, states, IDs and timestamps. No token, secret, address,\nemail, or request/response body is stored. It does not touch store.db.\n\nAtomic SQLite reservations protect concurrent workers sharing this same file.\nAlways reuse the same reference for the same logical order and preserve the\njournal. A different payload with the same reference is refused. A created record\nreturns its saved ID without authentication or another POST.\n\n- pending: reservation exists; a crashed process may have submitted the request.\n- not_sent: authentication failed before the creation call; same payload can retry.\n- rejected: creation returned HTTP 400; no automatic retry for this reference.\n- uncertain: timeout, cancellation, redirect, HTTP error other than 400, malformed\n  response, missing/invalid ID, or ambiguous result. Submission stays blocked.\n- created: HTTP 200 + status_code=200 + a positive numeric order_id was recorded,\n  or an operator registered an already confirmed test.\n\nDo not delete the journal, switch --journal paths, generate a new reference, or\nclear an uncertain/pending row merely to retry an ambiguous submission. Reconcile\nwith Qikink/dashboard/support first. The local guard cannot cover orders created\noutside it unless registered, or independent machines with different databases.\nA database commit failure after remote success can leave pending; keep it blocked.\n\nThe access token is cached until expiry within one client instance. Qikink's token\nendpoint replaces previous tokens; avoid competing token generators in separate\nprocesses. Authentication problems are surfaced; order POSTs are never replayed.\n\n## Offline verification\n\n```bash\n# From repository root; mocked HTTP, temporary SQLite, no remote orders:\nserver/.venv/bin/python -m unittest discover -s server/tests -p 'test_qikink*.py' -v\n```\n\nLive evidence supplied by the operator, not rerun by these tests:\nauthentication HTTP 200; plain creation HTTP 200, ID 24616032;\nlookup /api/order/list HTTP 404 and /api/order HTTP 500. Physical printed fulfillment,\nshipping quotes, tracking, payments, and production readiness remain unverified.\nThe DTG client is covered by offline tests; remote printed creation is not yet confirmed.\n\n## Offline catalog mapping and pricing worksheet\n\n`config/qikink_sandbox_catalog.json` is a draft template, not a store import. It\nrecords the operator-confirmed printed Sandbox order 24620736 / tbw_print001,\nSKU MVnHs-Wh-S and design tbw_print001_d. Store product/variant IDs, countries,\nactual supplier costs and FX remain unset. The logo mockup remains a placeholder.\nThis acceptance is not evidence of live inventory, supplier cost or shipping\ncoverage. The template never creates/updates products, variants, orders or prices.\n\n```bash\n.venv/bin/python scripts/qikink_sandbox.py catalog\n# Requested countries only; these flags do NOT assert shipping support:\n.venv/bin/python scripts/qikink_sandbox.py catalog --country US --country CL\n```\n\nThe report needs no Qikink credentials or HTTP calls. If product/variant IDs are\nprovided, it opens store.db using SQLite mode=ro, verifies that the variant\nbelongs to that product, and flags active records as unsuitable for this staging\nstep. A missing DB is reported, never created. This does not reassign an existing\nCJ, Printify or Lulu product to Qikink. Public sales are always disabled in this\nworksheet, even if every input is supplied.\n\nDo not put private supplier quotes in the committed template. Copy it to a local\nfile before adding commercial evidence, and keep that file outside Git:\n\n```bash\ncp -n config/qikink_sandbox_catalog.json data/qikink_catalog.local.json\n.venv/bin/python scripts/qikink_sandbox.py catalog --file data/qikink_catalog.local.json\n```\n\nDraftVariant.cost_quotes accepts only explicit itemized INR quotes for one unit,\nmatching the exact SKU, full design (code, dimensions, placement and image URLs),\ncountry, postal code and shipping method. Supply product,\nprinting, packaging, tax, shipping and other costs (an explicit confirmed zero is\nallowed), delivery range, source, confirmed_on and valid_until. Missing, expired,\nfuture-dated, wrong-country and wrong-SKU costs are not used. The selling value\n\"1\" used in Sandbox tests is NEVER read as a supplier quote.\n\nThe FX record requires INR_USD, a positive usd_per_inr, source and validity dates.\nThe CLI does not fetch or verify rates remotely. A dated operator-provided quote\nand FX source produce a planning estimate only:\n\n    cost_USD = sum(all six INR costs) * usd_per_inr\n    minimum_retail = (cost_USD + PAYPAL_FIXED + OPS_FIXED)\n                     / (1 - PAYPAL_PCT - MARGIN_PCT)\n\nThe worksheet uses the existing pricing configuration, respects MIN_PRICE and\nrounds upward to x.99. It includes shipping in the proposed retail price; it is\nnot an additional checkout shipping charge. It does not apply CJ cost-band rules.\nInvalid/nonfinite fee assumptions produce no price. Report dates use\nAmerica/Santiago. A quote for one postal code and one unit is not a promise of\ncountry-wide coverage, a multi-item basket rate or a tax/compliance assessment.\nCheckout wiring, currency conversion settlement, live credentials, actual SKU\navailability, other destinations, commercial artwork/mockups and full shipping\nrules remain separate requirements before public sales.\n"
}
HASHES = {'server/services/qikink.py': 'e59bdcf0d7b3d9ca0e8a5c841e97f856ccd67fb788e5f2a5402fb7fcd9a1a441', 'server/services/qikink_catalog.py': 'b23c50108a6addaf84f2ab6639b556cbb6fd7ceae6e313e766c0416e75552d55', 'server/scripts/qikink_sandbox.py': '995a659947d714dc29f26025a26aef7151a9bdd983cce2981223c348837b48e9', 'server/tests/test_qikink.py': '7eb452f591a445b67772fa52806d05f43e3578b72c8e3ba72942b97103022391', 'server/tests/test_qikink_catalog.py': 'a1002da206074d3777c9c1afb1911d5d4f0193c1c87ff6f6d260309e2f41c379', 'server/config/qikink_sandbox_catalog.json': '059a70b4ad545734609083be9ded01cc472e9edf26032b6a357c58b66422a636', 'server/docs/QIKINK_SANDBOX.md': '668ec6dc4286627e276b61c72813228c17adee59b00ac03a0b1addb263a78b82'}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--root", type=Path, default=Path("/var/www/thebookswanderer.com"))
    args = parser.parse_args()
    root = args.root.resolve()
    if not (root / "server" / ".env").is_file():
        raise RuntimeError("Server .env not found; nothing installed")

    # Run the Sandbox tests in isolation BEFORE replacing any target files.
    with tempfile.TemporaryDirectory(prefix="qikink-verify-") as staging:
        stage = Path(staging)
        for name, content in FILES.items():
            if hashlib.sha256(content.encode()).hexdigest() != HASHES[name]:
                raise RuntimeError("Package checksum mismatch")
            target = stage / name
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_text(content)
        # The worksheet reuses the store's existing pricing configuration.
        pricing = root / "server/services/pricing.py"
        if not pricing.is_file():
            raise RuntimeError("Existing pricing service not found; nothing installed")
        shutil.copy2(pricing, stage / "server/services/pricing.py")
        subprocess.run([sys.executable, "-m", "unittest", "discover", "-s",
                        str(stage / "server/tests"), "-p", "test_qikink*.py", "-v"],
                       cwd=stage, check=True)

    # Back up only previous versions of these package files when different.
    stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S%fZ")
    backup = root / "server/data/qikink-install-backups" / stamp
    for name, content in FILES.items():
        target = root / name
        target.parent.mkdir(parents=True, exist_ok=True)
        if target.exists():
            if target.read_text() == content:
                continue
            saved = backup / name
            saved.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(target, saved)
        fd, temp_name = tempfile.mkstemp(prefix=".qikink-install-", dir=target.parent)
        try:
            with os.fdopen(fd, "w") as stream:
                stream.write(content)
                stream.flush()
                os.fsync(stream.fileno())
                os.fchmod(stream.fileno(), 0o644)
            os.replace(temp_name, target)
        finally:
            if os.path.exists(temp_name):
                os.unlink(temp_name)

    # Local operator-confirmed record only: never call authenticate/create here.
    cli = [sys.executable, str(root / "server/scripts/qikink_sandbox.py")]
    subprocess.run(cli + ["remember", "--reference", "tbw_9ba7265277",
                         "--order-id", "24616032"], check=True)
    journal = root / "server/data/qikink_sandbox.db"
    os.chmod(journal, 0o600)
    if os.geteuid() == 0:
        user = pwd.getpwnam("www-data")
        os.chown(journal, user.pw_uid, user.pw_gid)
    subprocess.run(cli + ["status", "tbw_9ba7265277"], check=True)
    print("Instalación completada. Pedido 24616032 registrado localmente.")
    print("Sin llamadas a Qikink, pedidos nuevos, cambios en .env ni reinicio de la tienda.")
    if backup.exists():
        print("Copia de los archivos anteriores:", backup)


if __name__ == "__main__":
    try:
        main()
    except Exception as exc:
        print("Instalación incompleta:", type(exc).__name__)
        print("No se enviaron pedidos. No borres el registro; revisa el estado antes de continuar.")
        sys.exit(1)
